import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.DaCm-iTo.js";const u=JSON.parse('{"title":"PDC","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/corelib/pdc.md","filePath":"en/modules/corelib/pdc.md","lastUpdated":null}'),d={name:"en/modules/corelib/pdc.md"};function i(s,e,c,n,l,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="pdc" tabindex="-1">PDC <a class="header-anchor" href="#pdc" aria-label="Permalink to &quot;PDC&quot;">​</a></h1><p>PDC means Bukkit <code>PersistentDataContainer</code>. CoreLib uses it to store structured module state on items, block states, and other persistent holders. EmakiCooking now prefers block-entity PDC for station state and falls back to <code>data/stations/</code> YAML only for non-<code>TileState</code> station anchors.</p><h2 id="why-pdc-matters" tabindex="-1">Why PDC matters <a class="header-anchor" href="#why-pdc-matters" aria-label="Permalink to &quot;Why PDC matters&quot;">​</a></h2><p>Lore is display text, not reliable data. PDC is more suitable for real state such as item IDs, strengthening stars, forge quality, gem sockets, set pieces, skill IDs, and attribute payloads.</p><h2 id="namespace-rule" tabindex="-1">Namespace rule <a class="header-anchor" href="#namespace-rule" aria-label="Permalink to &quot;Namespace rule&quot;">​</a></h2><p>Each module should write its own namespace or source and avoid overwriting other module data. For example, Gem should not clear Strengthen data, and Strengthen should not clear Forge data.</p><h2 id="advice" tabindex="-1">Advice <a class="header-anchor" href="#advice" aria-label="Permalink to &quot;Advice&quot;">​</a></h2><p>Do not manually edit PDC in production. Use module commands or APIs to inspect, clear, or refresh state.</p><h2 id="where-shared-pdc-contracts-live-now" tabindex="-1">Where shared PDC contracts live now <a class="header-anchor" href="#where-shared-pdc-contracts-live-now" aria-label="Permalink to &quot;Where shared PDC contracts live now&quot;">​</a></h2><p>CoreLib used to host some cross-module PDC contracts. Those contracts have been moved to the owning API / protocol modules. New code should use the right-hand column:</p><table tabindex="0"><thead><tr><th>Data</th><th>Authoritative entry point</th><th>Legacy CoreLib entry point</th></tr></thead><tbody><tr><td>Equipment attribute PDC contract</td><td><code>EmakiAttributeApi</code> (in the <code>EmakiAttributeApi</code> module)</td><td><code>PdcAttributeGateway</code> and <code>EmakiAttributeBridge</code> were removed in CoreLib <code>4.6.7</code></td></tr><tr><td>Equipment skill PDC read/write</td><td><code>EquipmentSkillPdcCodec</code> (package <code>emaki.jiuwu.craft.skills.api.pdc</code> in the <code>EmakiSkillsApi</code> module)</td><td><code>SkillPdcGateway</code> was removed in CoreLib <code>4.6.7</code></td></tr></tbody></table><p>The CoreLib-side classes are kept as a compatibility surface for one synchronized release window and will be removed afterwards. Do not reference them from new code.</p><p>When you store structured data, keep a version number so you can migrate later. CoreLib&#39;s <code>SnapshotCodec</code> provides encoding, decoding, and version compatibility support.</p>',13)])])}const m=t(d,[["render",i]]);export{u as __pageData,m as default};
